import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, Optional, Union

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _to_datetime(value: Union[str, datetime]) -> datetime:
    if isinstance(value, datetime):
        dt = value
    else:
        s = value.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


def get_aggregated_metric_statistics(
    namespace: str,
    metric_name: str,
    start_time: Union[str, datetime],
    end_time: Union[str, datetime],
    period: int = 300,
    statistics: Optional[list] = None,
    dimensions: Optional[Dict[str, str]] = None,
    unit: Optional[str] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Retrieve aggregated statistics for an Amazon CloudWatch metric over a time window.

    Returns a normalized dictionary with the queried metric data and statistics.
    """
    if statistics is None:
        statistics = ["Average", "Sum", "Minimum", "Maximum", "SampleCount"]

    start_dt = _to_datetime(start_time)
    end_dt = _to_datetime(end_time)

    if end_dt <= start_dt:
        raise ValueError("end_time must be after start_time")
    if period <= 0:
        raise ValueError("period must be a positive integer")

    region = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    client = boto3.client("cloudwatch", region_name=region)

    metric_kwargs: Dict[str, Any] = {
        "Namespace": namespace,
        "MetricName": metric_name,
    }
    if dimensions:
        metric_kwargs["Dimensions"] = [
            {"Name": name, "Value": value} for name, value in dimensions.items()
        ]

    params: Dict[str, Any] = {
        "Namespace": namespace,
        "MetricName": metric_name,
        "StartTime": start_dt,
        "EndTime": end_dt,
        "Period": int(period),
        "Statistics": statistics,
    }
    if unit:
        params["Unit"] = unit
    if dimensions:
        params["Dimensions"] = metric_kwargs["Dimensions"]

    try:
        resp = client.get_metric_statistics(**params)
    except (BotoCoreError, ClientError) as exc:
        raise RuntimeError(f"CloudWatch get_metric_statistics failed: {exc}") from exc

    datapoints = resp.get("Datapoints", [])
    datapoints.sort(key=lambda d: d.get("Timestamp", datetime.min.replace(tzinfo=timezone.utc)))

    return {
        "namespace": namespace,
        "metric_name": metric_name,
        "dimensions": dimensions or {},
        "start_time": start_dt.isoformat(),
        "end_time": end_dt.isoformat(),
        "period": int(period),
        "statistics": statistics,
        "unit": unit,
        "datapoints": [
            {
                "timestamp": dp.get("Timestamp").isoformat() if dp.get("Timestamp") else None,
                "average": dp.get("Average"),
                "sum": dp.get("Sum"),
                "minimum": dp.get("Minimum"),
                "maximum": dp.get("Maximum"),
                "sample_count": dp.get("SampleCount"),
                "unit": dp.get("Unit"),
            }
            for dp in datapoints
        ],
        "label": resp.get("Label"),
    }
